const BUTTONS = [['fix', 'Fix it', 3, 'fix it', null], ['look', 'Look into it', 1, 'look into it', null], ['notbug', 'Not a bug', 2, 'not a bug, close it', 'Not a bug'],
  ['prog', 'In progress', 2, 'in progress', 'In progress'], ['done', 'Done', 2, 'done', 'Done']];
