  if (m) v = { id: +m[1] }; else if ((m = /guild\/([a-z]{2})\/([a-z0-9-]+)\/([^/?#]+)/i.exec(s))) v = { reg: m[1].toLowerCase(), srv: m[2].toLowerCase(), name: decodeURIComponent(m[3]).replace(/\+/g, ' ') };
